import { WaterfallData } from '../../PerformanceTool/types';

const PERIOD_ICON =
  'https://theloop20.test-abinbev.acsitefactory.com/sites/g/files/wnfebl11871/files/2025-03/ABI.png';

const BRAND_LOGOS: Record<string, string> = {
  corona:
    'https://assets-martech-uat.mybees-platform.dev/brands/corona/square.png',
  budweiser:
    'https://assets-martech-uat.mybees-platform.dev/brands/budweiser/square.png',
  antartica:
    'https://assets-martech-uat.mybees-platform.dev/brands/antarctica/square.png',
  skol: 'https://assets-martech-uat.mybees-platform.dev/brands/skol/square.png',
  original:
    'https://assets-martech-uat.mybees-platform.dev/brands/original/square.png',
  spaten:
    'https://assets-martech-uat.mybees-platform.dev/brands/spaten/square.png',
  brahma:
    'https://assets-martech-uat.mybees-platform.dev/brands/brahma/square.png',
};

export const watchTowerWaterfallMock: WaterfallData = {
  values: [136500, 8700, 11200, 5400, 4800, -7200, -5800, -6100, 147500],
  labels: [
    "YTD'25",
    'Corona',
    'Budweiser',
    'Antartica',
    'Skol',
    'Original',
    'Spaten',
    'Brahma',
    "YTD'26",
  ],
  formattedData: [
    [
      '136.5k',
      '8.7k',
      '11.2k',
      '5.4k',
      '4.8k',
      '-7.2k',
      '-5.8k',
      '-6.1k',
      '147.5k',
    ],
  ],
  images: {
    data: [
      { mainBrand: { src: PERIOD_ICON, alt: "YTD'25" }, title: "YTD'25" },
      {
        mainBrand: { src: BRAND_LOGOS.corona, alt: 'Corona' },
        title: 'Corona',
      },
      {
        mainBrand: { src: BRAND_LOGOS.budweiser, alt: 'Budweiser' },
        title: 'Budweiser',
      },
      {
        mainBrand: { src: BRAND_LOGOS.antartica, alt: 'Antartica' },
        title: 'Antartica',
      },
      { mainBrand: { src: BRAND_LOGOS.skol, alt: 'Skol' }, title: 'Skol' },
      {
        mainBrand: { src: BRAND_LOGOS.original, alt: 'Original' },
        title: 'Original',
      },
      {
        mainBrand: { src: BRAND_LOGOS.spaten, alt: 'Spaten' },
        title: 'Spaten',
      },
      {
        mainBrand: { src: BRAND_LOGOS.brahma, alt: 'Brahma' },
        title: 'Brahma',
      },
      { mainBrand: { src: PERIOD_ICON, alt: "YTD'26" }, title: "YTD'26" },
    ],
  },
  comparisonLine: {
    data: [
      {
        title: 'Contribution to Country',
        data: [
          { value: '-', measure: '' }, // YTD'25  — baseline, no trend
          { value: '1.1', measure: '%', trend: 'positive' }, // Corona    (+8.7k, green bar)
          { value: '1.6', measure: '%', trend: 'positive' }, // Budweiser (+11.2k, largest green)
          { value: '0.8', measure: '%', trend: 'positive' }, // Antartica (+5.4k, green bar)
          { value: '0.7', measure: '%', trend: 'positive' }, // Skol      (+4.8k, green bar)
          { value: '-1.1', measure: '%', trend: 'negative' }, // Original  (-7.2k, largest red)
          { value: '-0.9', measure: '%', trend: 'negative' }, // Spaten    (-5.8k, red bar)
          { value: '-0.9', measure: '%', trend: 'negative' }, // Brahma    (-6.1k, red bar)
          { value: '1.3', measure: '%', trend: 'positive' }, // YTD'26   (net +11k, positive)
        ],
      },
    ],
  },
};
